// Adapta o payload do ZapConnecta/Helena ao contrato do CRM
const body = $input.first().json.body ?? $input.first().json;

// Extrair telefone limpo
const telefone = (body.phone ?? body.telefone ?? '').replace(/\D/g, '');

// Mapear área jurídica
const AREAS = {
  previdenciario: 'previdenciario',
  inss: 'previdenciario',
  trabalhista: 'trabalhista',
  clt: 'trabalhista',
  consumidor: 'consumidor',
  cdc: 'consumidor',
  civil: 'civel',
  civel: 'civel',
};

const areaBruta = (body.area ?? body.assunto ?? '').toLowerCase();
const area = Object.entries(AREAS).find(([k]) => areaBruta.includes(k))?.[1] ?? null;

// Gerar external_id idempotente
const externalId = body.message_id ?? body.id ?? `wa_${telefone}_${Date.now()}`;

return [{
  json: {
    external_id:    externalId,
    nome:           body.name ?? body.nome ?? 'Não identificado',
    telefone:       telefone,
    email:          body.email ?? null,
    cpf:            body.cpf ?? null,
    area_juridica:  area,
    descricao_caso: body.message ?? body.mensagem ?? body.descricao ?? null,
    urgencia:       body.urgencia === true || body.urgencia === 'true',
    prazo_sensivel: body.prazo_sensivel === true,
    canal_origem:   'whatsapp',
    n8n_execution_id: $execution.id,
  }
}];
